#include "runtime/interpreter.hpp"
#include "plotting/field_animation.hpp"
#include <iostream>
#include <sstream>
using namespace penta;
int main(){int checks=0,failures=0;auto expect=[&](bool yes,const char* text){++checks;if(!yes){++failures;std::cerr<<text<<'\n';}};auto execute=[&](const std::string& source){auto result=runtime::execute(source);if(!result.ok()){for(const auto& d:result.analysis.diagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';for(const auto& d:result.runtimeDiagnostics)std::cerr<<d.code<<": "<<d.message<<'\n';}return result;};
    const std::string field="record field=options(dimension=2,x=[0,1],y=[0,1],t=[0,2],values=[0,1,2,3;6,7,8,9]);";
    expect(execute(field+"record probe=fieldprobe(field,[0.25,0.5;1,1]);assert(probe.probes==2);assert(abs(probe.values(1,1)-1.25)<1e-14);assert(abs(probe.values(2,1)-7.25)<1e-14);assert(probe.values(2,2)==9);").ok(),"Bilinear probes preserve an independent affine space/time reference.");
    const auto sliced=execute(field+"record slice=fieldslice(field,\"x\",0.25);assert(slice.dimension==1);assert(abs(slice.values(1,1)-0.25)<1e-14);assert(abs(slice.values(2,2)-8.25)<1e-14);animatefield(slice);animationframe(2);");expect(sliced.ok(),"Spatial slices retain full time histories and are directly animated.");if(sliced.ok()){expect(sliced.figureActions[0].animation->values==std::vector<double>({.25,2.25,6.25,8.25}),"Slice data is interpolated without changing the source field.");}
    expect(!execute(field+"record probe=fieldprobe(field,[-0.1,0]);").ok(),"Probe extrapolation rejects explicitly.");
    std::ostringstream source;source<<"record field=options(dimension=2,x=[0,1],y=[0,1],t=[0,2],components=16,value_layout=\"node_coefficients\",algebra_id=\"sedenion_coordinate_field\",values=[";for(unsigned time=0;time<2;++time){if(time)source<<';';for(unsigned node=0;node<4;++node)for(unsigned coefficient=0;coefficient<16;++coefficient){if(node||coefficient)source<<',';source<<coefficient+(node%2)+2*(node/2)+6*time;}}source<<"]);record probe=fieldprobe(field,[0.25,0.5]);assert(probe.components==16);assert(abs(probe.values(2,16)-22.25)<1e-14);record slice=fieldslice(field,\"y\",0.5);animatefield(slice,options(component=15));";const auto wide=execute(source.str());expect(wide.ok(),"Probes/slices and animation preserve all16 sedenion field coordinates.");if(wide.ok()){const auto animation=wide.figureActions[0].animation;expect(animation->components==16&&animation->basisLabels.size()==16,"Wide animation retains complete coordinate metadata.");const auto frame=plotting::fieldAnimationFrame(*animation,1);expect(frame.curves[0].points[1][1]==23,"Wide field frames select the exact retained coordinate/sample.");}
    std::cout<<checks<<" field probe/slice checks, "<<failures<<" failures\n";return failures?1:0;
}
